skip_dirs = {'node_modules', '.gradle', 'build', 'dist', '__pycache__', 
             '.tmp-frames', '.tmp-ivx-frames', 'node_modules-full',
             'logs'}  # logs are runtime artifacts, not source code
skip_exts = {'.png', '.jpg', '.jpeg', '.gif', '.webp', '.ico', 
             '.woff', '.woff2', '.ttf', '.otf', '.bin', '.apk', '.aar', 
             '.jar', '.dex', '.so', '.pyc', '.lock'}
skip_files = {'.gitignore', '.gitattributes', '.gitmodules'}

local_files = []
for root, dirs, files in os.walk('.'):
    # Skip hidden dirs, node_modules, logs, build artifacts
    dirs[:] = [d for d in dirs if d not in skip_dirs and not d.startswith('.git')]
    for f in files:
        ext = os.path.splitext(f)[1].lower()
        if ext in skip_exts:
            continue
        if f in skip_files:
            continue
        if f.startswith('.pyc'):
            continue
        filepath = os.path.join(root, f)
        if filepath.startswith('./'):
            filepath = filepath[2:]
        # Skip .rork history files (Rork internal, not source code)
        if filepath.startswith('.rork/history/'):
            continue
        if filepath.startswith('.rork/plans/'):
            continue
        if filepath.startswith('.rork/skills'):
            continue
        if filepath.startswith('.rork/swift-template'):
            continue
        local_files.append(filepath)

local_files.sort()
print(f"Local source files (excl logs/.rork): {len(local_files)}")

# Find files NOT on GitHub
missing = []
for f in local_files:
    if f not in github_paths:
        missing.append(f)

print(f"Missing from GitHub: {len(missing)}")

# Save missing list
with open('/tmp/missing_files.json', 'w') as f:
    json.dump(missing, f)

# Print categories
categories = {}
for f in missing:
    top = f.split('/')[0] if '/' in f else 'root'
    categories[top] = categories.get(top, 0) + 1

print("\nMissing by category:")
for cat, count in sorted(categories.items(), key=lambda x: -x[1]):
    print(f"  {cat}: {count}")

# Calculate total size
total_size = 0
for f in missing:
    try:
        total_size += os.path.getsize(f)
    except:
        pass
print(f"\nTotal size of missing files: {total_size:,} bytes ({total_size/1024/1024:.1f} MB)")

# Check for files over 1.5MB (API limit)
oversized = []
for f in missing:
    try:
        sz = os.path.getsize(f)
        if sz > 1500000:
            oversized.append((f, sz))
    except:
        pass
print(f"\nFiles over 1.5MB limit: {len(oversized)}")
for f, sz in oversized:
    print(f"  {f}: {sz:,} bytes")
